trait Describable {
    fn describe(&self) -> String;
}

struct Article {
    title: String,
}

fn describe_all<T>(items: &[T]) -> Vec<String> {
    // TODO: require Describable
    items.iter().map(|item| item.describe()).collect()
}

fn main() {
    let article = Article { title: String::from("Campus power") };
    println!("{:?}", describe_all(&[article]));
}
